package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.charset.StandardCharsets;
public class NativeRewardsEntryProtocolTest {
 static final String N="0123456789abcdef0123456789abcdef";
 interface Bad{void run();}void reject(Bad r){try{r.run();fail();}catch(IllegalArgumentException e){}}
 @Test public void exactPreparedRoundTrip(){var p=new NativeRewardsEntryProtocol.Prepared(N,8,0,4,100,20,5);assertEquals(p,NativeRewardsEntryProtocol.parsePrepared(NativeRewardsEntryProtocol.encode(p),N,8,90,200,110));}
 @Test public void exactResultRoundTrip(){var r=new NativeRewardsEntryProtocol.Result(N,8,NativeRewardsEntryProtocol.Reason.OK,NativeRewardsEntryProtocol.Cleanup.CONFIRMED,true,true,100,120,130);assertEquals(r,NativeRewardsEntryProtocol.parseResult(NativeRewardsEntryProtocol.encode(r),N,8,100,200,140));}
 @Test public void wrongNonceOrTaskRejected(){String l=NativeRewardsEntryProtocol.encode(new NativeRewardsEntryProtocol.Prepared(N,8,0,4,100,20,5));reject(()->NativeRewardsEntryProtocol.parsePrepared(l,"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",8,90,200,110));reject(()->NativeRewardsEntryProtocol.parsePrepared(l,N,9,90,200,110));}
 @Test public void expiredOrFuturePreparedRejected(){String l=NativeRewardsEntryProtocol.encode(new NativeRewardsEntryProtocol.Prepared(N,8,0,4,100,20,5));reject(()->NativeRewardsEntryProtocol.parsePrepared(l,N,8,101,200,110));reject(()->NativeRewardsEntryProtocol.parsePrepared(l,N,8,90,200,99));reject(()->NativeRewardsEntryProtocol.parsePrepared(l,N,8,90,110,110));}
 @Test public void unknownCleanupCannotClaimSuccess(){reject(()->new NativeRewardsEntryProtocol.Result(N,8,NativeRewardsEntryProtocol.Reason.OK,NativeRewardsEntryProtocol.Cleanup.UNKNOWN,true,true,100,120,130));}
 @Test public void actionCannotPrecedePrepared(){reject(()->new NativeRewardsEntryProtocol.Result(N,8,NativeRewardsEntryProtocol.Reason.ACTION_FALSE,NativeRewardsEntryProtocol.Cleanup.CONFIRMED,true,false,-1,120,130));}
 @Test public void commitRequiresEntireExactFrame(){byte[] x=NativeRewardsEntryProtocol.commit(N).getBytes(StandardCharsets.US_ASCII);assertTrue(NativeRewardsEntryProtocol.validCommit(x,x.length,N));assertFalse(NativeRewardsEntryProtocol.validCommit(x,x.length-1,N));assertFalse(NativeRewardsEntryProtocol.validCommit((NativeRewardsEntryProtocol.commit(N)+"x").getBytes(StandardCharsets.US_ASCII),x.length+1,N));}
 @Test public void duplicateCommitRejected(){byte[] x=(NativeRewardsEntryProtocol.commit(N)+NativeRewardsEntryProtocol.commit(N)).getBytes(StandardCharsets.US_ASCII);assertFalse(NativeRewardsEntryProtocol.validCommit(x,x.length,N));}
 @Test public void malformedAndOversizedFrameRejected(){reject(()->NativeRewardsEntryProtocol.parsePrepared("x".repeat(513),N,8,1,200,100));reject(()->NativeRewardsEntryProtocol.parsePrepared("ERP1|"+N+"|MAIN|08|0|4|100|20|5",N,8,1,200,100));}
 @Test public void actualCompleteIdentityMatches(){assertTrue(NativeRewardsEntryProtocol.eligible("com.microsoft.bing","com.microsoft.bing:id/glance_card_container","Rewards",true,true,true));}
 @Test public void selectorNeverFallsBack(){String id="com.microsoft.bing:id/glance_card_container";assertFalse(NativeRewardsEntryProtocol.eligible("other",id,"Rewards",true,true,true));assertFalse(NativeRewardsEntryProtocol.eligible("com.microsoft.bing",id+"x","Rewards",true,true,true));assertFalse(NativeRewardsEntryProtocol.eligible("com.microsoft.bing",id,"Rewards ",true,true,true));assertFalse(NativeRewardsEntryProtocol.eligible("com.microsoft.bing",id,"Rewards",false,true,true));assertFalse(NativeRewardsEntryProtocol.eligible("com.microsoft.bing",id,"Rewards",true,false,true));assertFalse(NativeRewardsEntryProtocol.eligible("com.microsoft.bing",id,"Rewards",true,true,false));}
 @Test public void bindingCannotTargetOwnTask(){reject(()->new NativeRewardsEntryProtocol.Binding(N,200,8,1080,2400,0,10001,10002,10003,8));}
 @Test public void templatePreparedIsSeparateTypedHeader(){var p=new NativeRewardsEntryProtocol.Prepared(N,8,0,4,100,20,5);String line=NativeRewardsEntryProtocol.encodeTemplatePrepared(p);assertTrue(line.startsWith("ERP2|"+N+"|TEMPLATE|"));assertEquals(p,NativeRewardsEntryProtocol.parseTemplatePrepared(line,N,8,90,200,110));reject(()->NativeRewardsEntryProtocol.parsePrepared(line,N,8,90,200,110));reject(()->NativeRewardsEntryProtocol.parseTemplatePrepared(NativeRewardsEntryProtocol.encode(p),N,8,90,200,110));}
 @Test public void templatePreparedRejectsWrongRoleNonceTaskAndTime(){String line=NativeRewardsEntryProtocol.encodeTemplatePrepared(new NativeRewardsEntryProtocol.Prepared(N,8,0,4,100,20,5));reject(()->NativeRewardsEntryProtocol.parseTemplatePrepared(line.replace("TEMPLATE","MAIN"),N,8,90,200,110));reject(()->NativeRewardsEntryProtocol.parseTemplatePrepared(line,"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",8,90,200,110));reject(()->NativeRewardsEntryProtocol.parseTemplatePrepared(line,N,9,90,200,110));reject(()->NativeRewardsEntryProtocol.parseTemplatePrepared(line,N,8,101,200,110));reject(()->NativeRewardsEntryProtocol.parseTemplatePrepared(line,N,8,90,200,99));reject(()->NativeRewardsEntryProtocol.parseTemplatePrepared(line,N,8,90,110,110));}
 @Test public void mainWireBytesStayExact(){var p=new NativeRewardsEntryProtocol.Prepared(N,8,0,4,100,20,5);assertEquals("ERP1|"+N+"|MAIN|8|0|4|100|20|5",NativeRewardsEntryProtocol.encode(p));}
}
